func TestRepositoryCursor(t *testing.T) {
	db := openFixtureDB(t)
	ctx := context.Background()
	repo := products.NewRepository(db)
	want := map[int64]bool{}
	for range 3 {
		want[fixtureProduct(t, ctx, db).ID] = true
	}
	first, err := repo.List(ctx, products.ListParams{Limit: 1})
	if err != nil || first.Total == nil || first.NextCursor == nil {
		t.Fatalf("an offset page with more rows has no cursor: %+v %v", first, err)
	}
	seen := map[int64]bool{}
	p := products.ListParams{Limit: 2}
	for pages := 0; ; pages++ {
		if pages > 10000 {
			t.Fatal("cursor pagination does not end")
		}
		page, err := repo.List(ctx, p)
		if err != nil {
			t.Fatalf("list: %v", err)
		}
		if p.Cursor != nil && page.Total != nil {
			t.Fatal("a cursor page counted the rows")
		}
		for _, item := range page.Items {
			if seen[item.ID] {
				t.Fatalf("%v appeared on two pages", item.ID)
			}
			seen[item.ID] = true
		}
		if page.NextCursor == nil {
			break
		}
		cursor, err := products.ParseCursor(*page.NextCursor)
		if err != nil {
			t.Fatalf("parse cursor %q: %v", *page.NextCursor, err)
		}
		p.Cursor = &cursor
	}
	for id := range want {
		if !seen[id] {
			t.Fatalf("cursor pagination skipped %v", id)
		}
	}
	for _, bad := range []string{"", "not a cursor", "e30"} {
		if _, err := products.ParseCursor(bad); !errors.Is(err, products.ErrInvalidCursor) {
			t.Errorf("ParseCursor(%q) = %v", bad, err)
		}
	}
}

func TestRepositoryWithTx(t *testing.T) {
	db := openFixtureDB(t)
	ctx := context.Background()
	repo := products.NewRepository(db)
	in := fixtureProductInput(t, ctx, db)
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		t.Fatalf("begin: %v", err)
	}
	created, err := repo.WithTx(tx).Create(ctx, in)
	if err != nil {
		tx.Rollback()
		t.Fatalf("create in transaction: %v", err)
	}
	if _, err := repo.WithTx(tx).Get(ctx, created.ID); err != nil {
		tx.Rollback()
		t.Fatalf("get in transaction: %v", err)
	}
	if err := tx.Rollback(); err != nil {
		t.Fatalf("rollback: %v", err)
	}
	if _, err := repo.Get(ctx, created.ID); !errors.Is(err, database.ErrNotFound) {
		t.Fatalf("rolled back row is visible: %v", err)
	}
	next := fixtureProductInput(t, ctx, db)
	var committed products.Product
	err = database.InTx(ctx, db, func(tx *sql.Tx) error {
		var err error
		committed, err = repo.WithTx(tx).Create(ctx, next)
		return err
	})
	if err != nil {
		t.Fatalf("InTx: %v", err)
	}
	purgeProduct(t, db, committed.ID)
	if _, err := repo.Get(ctx, committed.ID); err != nil {
		t.Fatalf("committed row is missing: %v", err)
	}
}

